mapper.select:
SELECT id, type FROM (
    SELECT id, 'comment' AS type, gmt_create FROM workitem_comment
    WHERE tenant_id = #{tenantId} AND workitem_id = #{workitemId} AND source_type = 'WORKITEM'
    UNION ALL
    SELECT id, 'system' AS type, gmt_create FROM workitem_event
    WHERE tenant_id = #{tenantId} AND workitem_id = #{workitemId}
) timeline ORDER BY gmt_create DESC, id DESC, type DESC LIMIT 51 OFFSET #{offset}

